function userRow(): array { if (empty($_SESSION['uid'])) fail('UNAUTHENTICATED','Debes iniciar sesión.',401); $q=db()->prepare('SELECT * FROM usuarios WHERE id=? AND activo=1'); $q->execute([$_SESSION['uid']]); $u=$q->fetch(); if(!$u) fail('UNAUTHENTICATED','La sesión ya no es válida.',401); return $u; }
function state(int $uid): array { $q=db()->prepare('SELECT estado_json FROM gs_estado_usuario WHERE usuario_id=?'); $q->execute([$uid]); $v=$q->fetchColumn(); return $v ? (json_decode($v,true) ?: []) : ['points'=>['balance'=>0,'earned'=>0,'used'=>0],'movements'=>[],'orders'=>[],'library'=>[],'redeemed'=>[],'coupons'=>[]]; }
