function isAdmin(array $u): void { if($u['rol']!=='admin') fail('FORBIDDEN','Se requieren permisos de administrador.',403); }
function pointsMove(array &$s,int $delta,string $kind,string $concept,?string $ref=null): void { $s['points']['balance']=max(0,(int)$s['points']['balance']+$delta); if($kind==='compra')$s['points']['earned']+=$delta; elseif($kind==='reversa')$s['points']['earned']=max(0,$s['points']['earned']+$delta); elseif(in_array($kind,['canje','descuento'],true))$s['points']['used']+=-$delta; elseif($kind==='reembolso')$s['points']['used']=max(0,$s['points']['used']-$delta); array_unshift($s['movements'],['id'=>'M-'.bin2hex(random_bytes(5)),'date'=>date('c'),'kind'=>$kind,'concept'=>$concept,'points'=>$delta,'balance'=>$s['points']['balance'],'ref'=>$ref]); }
function decorated(array $o): array {
 if(($o['status']??'')==='Cancelado'){ $o['tracking']=['physical'=>null,'digital'=>null];$o['statusLabel']='Cancelado';$o['finished']=true;return $o; }
